#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    int stack[] = {8, 2}, top = 2;
    int right = stack[--top];
    int left = stack[--top];
    printf("%d\n", left - right);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    char s[] = "23+4*";
    int top = 0;
    for (int i = 0; s[i]; i++) {
        if (s[i] >= '0' && s[i] <= '9') {
            top++;
        } else {
            top--;
        }
    }
    printf("%d\n", top);
    return 0;
}

